/** Bindings and public vars are generated by `pnpm types`; secrets are never committed. */
export interface RuntimeEnv extends A2AEnv {
  SELF_SERVICE_ENABLED?: string;
  SHARED_INBOXES_ENABLED?: string;
  SESSION_KEY: string;
  CALLBACK_SENDER_TOKEN: string;
  /** Only accepted in the explicitly local test environment. Never a production auth path. */
  LOCAL_TEST_JWKS?: string;
}
export const READ_SCOPE = 'a2a:read';
export const WRITE_SCOPE = 'a2a:write';
export const ADMIN_SCOPE = 'a2a:admin';
export const EVENT_NAME = 'inbox.message.created';
export const VERSION = '0.1.0';
